    # Loop through all possible pairs of numbers, storing min and min_pair as they change
    for i in range(len(numbers)):
        for j in range(i + 1, len(numbers)):
            if abs(numbers[i] - numbers[j]) < min:
                min = abs(numbers[i] - numbers[j])
                min_pair = (numbers[i], numbers[j])
    # Ensure the numbers in the pair are in the correct order
