    ordered_nums = [0] * len(nums)
    ordered_keys = sorted(point_map.keys())
    ordered_indexes = []
    for key in ordered_keys:
        ordered_indexes += point_map[key]
    for i, index in enumerate(ordered_indexes):
        ordered_nums[i] = nums[index]
    return ordered_nums

